"use client";
import React,{useState} from "react";import Link from "next/link";import api from "@/lib/api";
import {useResource,Table,Badge,Notice,button,field,date,message} from "@/components/BillingUI";
interface Voucher{id:number;code:string;status:string;packageName:string;price:number;customerId:number|null;customerName:string|null;customerPhone:string|null;batchReference:string|null;saleType:string;delivery:string;archived:boolean;createdAt:string;firstLogin:string|null;expiresAt:string|null}
interface Customer{id:number;name:string}
export default function VouchersPage(){const {data,loading,error,load}=useResource<Voucher>("/api/vouchers");const customers=useResource<Customer>("/api/customers");const [tab,setTab]=useState("AVAILABLE");const [selected,setSelected]=useState<string[]>([]);const [customer,setCustomer]=useState("");const [note,setNote]=useState("");const routers=useResource<{id:number;name:string}>("/api/routers");const [sale,setSale]=useState(false);const [router,setRouter]=useState("");const [amount,setAmount]=useState("");const [method,setMethod]=useState("CASH");
 const sell=async(e:React.FormEvent)=>{e.preventDefault();if(selected.length!==1)return;try{await api.post(`/api/vouchers/${selected[0]}/sale`,{routerId:Number(router),amount:Number(amount),method});setSale(false);setSelected([]);setNote("Walk-in payment recorded.");await load();}catch(e){setNote(message(e));}};
 const tabs=["AVAILABLE","ONLINE","WALK_IN","EXPIRED","ARCHIVED","GIVEAWAY","ALL"];
 const matches=(v:Voucher,t:string)=>t==="ALL"?true:t==="ARCHIVED"?v.archived:v.archived?false:t==="AVAILABLE"?v.status==="unused"&&v.saleType!=="GIVEAWAY":t==="EXPIRED"?["expired","revoked"].includes(v.status):v.saleType===t;
 const action=async(v:Voucher)=>{if(!confirm(`Revoke ${v.code}?`))return;try{await api.post(`/api/vouchers/${v.code}/revoke`);await load();}catch(e){setNote(message(e));}};
 const assign=async()=>{try{await api.post("/api/vouchers/assign",{codes:selected,customerId:Number(customer)});setSelected([]);setNote("Vouchers assigned to customer.");await load();}catch(e){setNote(message(e));}};
 const exportCsv=()=>{const rows=data.filter(v=>selected.includes(v.code));const csv=[["Voucher","Package","Price UGX","Batch"],...rows.map(v=>[v.code,v.packageName,String(v.price),v.batchReference||""])].map(row=>row.map(x=>'"'+x.replace(/"/g,'""').replace(/^[=+@-]/,"'")+'"').join(",")).join("\r\n");const url=URL.createObjectURL(new Blob([csv],{type:"text/csv"}));const a=document.createElement("a");a.href=url;a.download="vouchers.csv";a.click();URL.revokeObjectURL(url);};
 return <div className="mx-auto max-w-7xl space-y-6"><div className="flex flex-wrap justify-between gap-4"><div><h1 className="text-2xl font-semibold text-slate-900">Vouchers</h1><p className="mt-2 text-sm text-slate-500">Generate access codes, organize batches, and track customer use.</p></div><Link href="/dashboard/vouchers/new" className={button}>Generate vouchers</Link></div><Notice text={error||note}/><div className="flex flex-wrap gap-2">{tabs.map(t=><button key={t} onClick={()=>setTab(t)} className={`rounded-lg border px-3 py-2 text-xs ${t===tab?"border-blue-500/40 bg-blue-50 text-blue-700":"border-slate-300 text-slate-500"}`}>{t.replace("_"," ")} <span className="ml-1">{data.filter(v=>matches(v,t)).length}</span></button>)}</div>
 <div className="flex flex-wrap items-center gap-3"><span className="text-xs text-slate-500">{selected.length} selected</span><select aria-label="Customer for voucher assignment" value={customer} onChange={e=>setCustomer(e.target.value)} className={`${field} !mt-0 !w-auto`}><option value="">Assign to customer</option>{customers.data.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select><button disabled={!selected.length||!customer} onClick={assign} className={button}>Bulk assign</button><button disabled={!selected.length} onClick={exportCsv} className="text-xs text-blue-700 disabled:opacity-40">Export selected CSV</button></div>
 {selected.length===1&&<button onClick={()=>{setSale(!sale);setAmount(String(data.find(v=>v.code===selected[0])?.price||""));}} className={button}>Record walk-in sale</button>}
 {sale&&<form onSubmit={sell} className="grid gap-3 rounded-xl border border-slate-200 bg-white p-4 sm:grid-cols-4"><label className="text-xs text-slate-500">Router<select required value={router} onChange={e=>setRouter(e.target.value)} className={field}><option value="">Select router</option>{routers.data.map(r=><option key={r.id} value={r.id}>{r.name}</option>)}</select></label><label className="text-xs text-slate-500">Amount received (UGX)<input type="number" required min="0.01" step="0.01" value={amount} onChange={e=>setAmount(e.target.value)} className={field}/></label><label className="text-xs text-slate-500">Method<select value={method} onChange={e=>setMethod(e.target.value)} className={field}>{["CASH","MTN","AIRTEL","BANK","OTHER"].map(m=><option key={m}>{m}</option>)}</select></label><button className={button}>Record payment</button></form>}
 <Table rows={data.filter(v=>matches(v,tab))} loading={loading} columns={[
 {label:"Select",render:v=><input aria-label={`Select ${v.code}`} type="checkbox" checked={selected.includes(v.code)} onChange={e=>setSelected(e.target.checked?[...selected,v.code]:selected.filter(c=>c!==v.code))}/>},
 {label:"Voucher code",render:v=><Badge tone="green">{v.code}</Badge>},{label:"Package",render:v=>v.packageName},{label:"Status",render:v=><Badge tone={["expired","revoked"].includes(v.status)?"red":"green"}>{v.status}</Badge>},{label:"Sale type",render:v=>v.saleType},{label:"Batch",render:v=>v.batchReference||"—"},{label:"Customer",render:v=>v.customerName||"—"},{label:"Phone",render:v=>v.customerPhone||"—"},{label:"Generated",render:v=>date(v.createdAt)},{label:"First login",render:v=>date(v.firstLogin)},{label:"Expires",render:v=>date(v.expiresAt)},{label:"Action",render:v=><button disabled={["expired","revoked"].includes(v.status)} onClick={()=>action(v)} className="text-red-600 disabled:opacity-30">Revoke</button>}
 ]}/></div>;
}
